package com.acme.dataservice

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.request.*
import io.ktor.server.response.*
import io.ktor.server.routing.*
import io.ktor.http.*
import java.io.ByteArrayInputStream
import java.io.ObjectInputStream
import java.util.Base64

// Feature flag client interface for dependency injection
interface FeatureFlagClient {
    fun getBooleanValue(flagKey: String, defaultValue: Boolean, context: Map<String, String>): Boolean
}

// Split.io SDK wrapper
class SplitFeatureFlagClient(private val splitClient: Any?) : FeatureFlagClient {
    override fun getBooleanValue(flagKey: String, defaultValue: Boolean, context: Map<String, String>): Boolean {
        // Delegates to Split SDK getTreatment()
        // Returns the evaluated treatment as boolean
        return try {
            val treatment = evaluateTreatment(flagKey, context)
            treatment == "on"
        } catch (e: Exception) {
            defaultValue
        }
    }

    private fun evaluateTreatment(flagKey: String, context: Map<String, String>): String {
        // Split SDK call - returns "on", "off", or "control"
        // In production this calls Split cloud evaluation
        return System.getenv("SPLIT_OVERRIDE_${flagKey.uppercase()}") ?: "off"
    }
}

// Legacy cache deserialization handler - used for migrating from old binary cache format
fun deserializeLegacyCacheEntry(serializedData: String): Any? {
    val bytes = Base64.getDecoder().decode(serializedData)
    val bais = ByteArrayInputStream(bytes)
    val ois = ObjectInputStream(bais)
    return ois.readObject()
}

// Modern JSON-based cache entry parser
fun parseModernCacheEntry(jsonData: String): Map<String, Any> {
    // Simple JSON parsing for cache entries
    return mapOf("data" to jsonData, "format" to "json", "version" to 2)
}

fun Application.module(featureFlagClient: FeatureFlagClient) {
    routing {
        post("/api/v1/cache/import") {
            val body = call.receiveText()
            val clientId = call.request.header("X-Client-ID") ?: "anonymous"
            val format = call.request.queryParameters["format"] ?: "json"

            val context = mapOf("clientId" to clientId, "environment" to (System.getenv("DEPLOY_ENV") ?: "production"))

            when (format) {
                "legacy_binary" -> {
                    // Check feature flag: legacy_binary_cache_import
                    // This path uses Java deserialization for backward compat with v1 clients
                    val legacyEnabled = featureFlagClient.getBooleanValue(
                        "legacy_binary_cache_import",
                        false,
                        context
                    )

                    if (legacyEnabled) {
                        try {
                            val obj = deserializeLegacyCacheEntry(body)
                            call.respondText("Imported legacy cache entry: ${obj?.javaClass?.name}", status = HttpStatusCode.OK)
                        } catch (e: Exception) {
                            call.respondText("Failed to import: ${e.message}", status = HttpStatusCode.BadRequest)
                        }
                    } else {
                        call.respondText(
                            "Legacy binary format is disabled. Use format=json",
                            status = HttpStatusCode.Gone
                        )
                    }
                }
                "json" -> {
                    val entry = parseModernCacheEntry(body)
                    call.respondText("Imported cache entry (v${entry["version"]})", status = HttpStatusCode.OK)
                }
                else -> {
                    call.respondText("Unsupported format: $format", status = HttpStatusCode.BadRequest)
                }
            }
        }

        get("/health") {
            call.respondText("OK")
        }
    }
}

fun main() {
    val splitClient = SplitFeatureFlagClient(null)
    embeddedServer(Netty, port = 8080) {
        module(splitClient)
    }.start(wait = true)
}
